const now = new Date();
const etDate = new Intl.DateTimeFormat("en-CA", {
  timeZone: "America/New_York",
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
}).format(now);

const etParts = new Intl.DateTimeFormat("en-US", {
  timeZone: "America/New_York",
  weekday: "short",
  hour: "2-digit",
  minute: "2-digit",
  hour12: false
}).formatToParts(now);

const getPart = (type) => etParts.find(p => p.type === type)?.value;
const weekday = getPart("weekday");
const hour = Number(getPart("hour"));
const minute = Number(getPart("minute"));
const isWeekday = !["Sat", "Sun"].includes(weekday);

return [{
  json: {
    should_run: isWeekday,
    et_date: etDate,
    et_weekday: weekday,
    et_hour: hour,
    et_minute: minute,
    fr_publication_date: etDate,
    public_inspection_endpoint: "current",
    note: "Runs only on weekdays. Fetches official Federal Register published docs and Public Inspection docs, tracks all papers in Postgres, and passes eligible unprocessed published papers to the Email Processor API."
  }
}];

const response = $input.first().json;
const docs = Array.isArray(response.results) ? response.results : [];

function ymd(value) {
  if (!value) return "";
  return String(value).slice(0, 10);
}

function agencyNames(doc) {
  return (doc.agencies || [])
    .map(a => a.name || a.raw_name || "")
    .filter(Boolean)
    .join("; ");
}

return docs.map(doc => {
  const documentNumber = doc.document_number || doc.documentNumber || "";
  const publicationDate = ymd(doc.publication_date);

  return {
    json: {
      id: documentNumber || doc.html_url || doc.pdf_url || doc.title,
      document_number: documentNumber,
      title: doc.title || "",
      agency: agencyNames(doc),
      abstract: doc.abstract || doc.excerpts || "",
      document_type: doc.type || "",
      publication_date: publicationDate,
      declared_publication_date: publicationDate,
      source_stream: "federal_register",
      filing_type: "published",
      filing_tag: "FEDERAL_REGISTER_PUBLISHED",
      status: "published",
      html_url: doc.html_url || "",
      pdf_url: doc.pdf_url || "",
      comment_url: doc.comment_url || "",
      filed_at: "",
      process_after_date: publicationDate,
      raw_json: doc
    }
  };
});

const response = $input.first().json;
const docs = Array.isArray(response.public_inspection_documents)
  ? response.public_inspection_documents
  : Array.isArray(response.results)
    ? response.results
    : [];

function ymd(value) {
  if (!value) return "";
  return String(value).slice(0, 10);
}

function agencyNames(doc) {
  return (doc.agencies || [])
    .map(a => a.name || a.raw_name || "")
    .filter(Boolean)
    .join("; ");
}

function inferFilingType(doc) {
  const rawType = String(doc.filing_type || doc.public_inspection_filing_type || doc.category || doc.status || "").toLowerCase();
  const filedAt = String(doc.filed_at || doc.file_date || doc.filed_on || "").toLowerCase();

  if (rawType.includes("special") || doc.special_filing === true) return "special";

  // Regular public inspection filings normally happen at 8:45 a.m. ET.
  // If the API exposes a different filed time, treat it as special.
  if (filedAt && !filedAt.includes("08:45") && !filedAt.includes("8:45")) return "special";

  return "regular";
}

return docs.map(doc => {
  const documentNumber = doc.document_number || doc.documentNumber || "";
  const declaredPublicationDate = ymd(
    doc.publication_date ||
    doc.scheduled_publication_date ||
    doc.scheduled_publication ||
    doc.publicationDate
  );

  const filingType = inferFilingType(doc);
  const tag = filingType === "special"
    ? "SPECIAL_PUBLIC_INSPECTION"
    : "REGULAR_PUBLIC_INSPECTION";

  return {
    json: {
      id: documentNumber || doc.html_url || doc.pdf_url || doc.title,
      document_number: documentNumber,
      title: doc.title || "",
      agency: agencyNames(doc),
      abstract: doc.abstract || doc.excerpts || "",
      document_type: doc.type || "",
      publication_date: declaredPublicationDate,
      declared_publication_date: declaredPublicationDate,
      source_stream: "public_inspection",
      filing_type: filingType,
      filing_tag: tag,
      status: "public_inspection_scheduled",
      html_url: doc.html_url || doc.public_inspection_url || "",
      pdf_url: doc.pdf_url || doc.public_inspection_pdf_url || "",
      comment_url: doc.comment_url || "",
      filed_at: doc.filed_at || doc.file_date || doc.filed_on || "",
      process_after_date: declaredPublicationDate,
      raw_json: doc
    }
  };
});

const items = $input.all().map(i => i.json);
const byId = new Map();

function score(doc) {
  // Prefer official publication over public inspection when the same doc appears twice.
  let s = 0;
  if (doc.source_stream === "federal_register") s += 100;
  if (doc.filing_tag === "SPECIAL_PUBLIC_INSPECTION") s += 10;
  if (doc.comment_url) s += 5;
  return s;
}

for (const doc of items) {
  if (!doc.id) continue;
  const existing = byId.get(doc.id);

  if (!existing || score(doc) > score(existing)) {
    // Preserve special tag if it was already discovered in Public Inspection.
    if (existing?.filing_tag === "SPECIAL_PUBLIC_INSPECTION" && doc.filing_tag === "FEDERAL_REGISTER_PUBLISHED") {
      doc.filing_tag = "SPECIAL_PUBLIC_INSPECTION";
      doc.filing_type = "special";
    }
    byId.set(doc.id, doc);
  }
}

const sorted = Array.from(byId.values()).sort((a, b) => {
  const d = String(a.publication_date || "").localeCompare(String(b.publication_date || ""));
  if (d !== 0) return d;
  if (a.filing_tag === "SPECIAL_PUBLIC_INSPECTION" && b.filing_tag !== "SPECIAL_PUBLIC_INSPECTION") return -1;
  if (a.filing_tag !== "SPECIAL_PUBLIC_INSPECTION" && b.filing_tag === "SPECIAL_PUBLIC_INSPECTION") return 1;
  return String(a.title || "").localeCompare(String(b.title || ""));
});

return sorted.map(doc => ({ json: doc }));

const response = $input.first().json;

if (Array.isArray(response.public_inspection_documents) || Array.isArray(response.results)) {
  return [{ json: response }];
}

return [
  {
    json: {
      public_inspection_documents: [],
      results: [],
      fetch_warning: "Public Inspection API failed or returned non-JSON response. Continuing workflow with empty Public Inspection records.",
      original_error: response
    }
  }
];

const response = $input.first().json;

if (Array.isArray(response.results)) {
  return [{ json: response }];
}

return [
  {
    json: {
      results: [],
      fetch_warning: "Federal Register API failed or returned non-JSON response. Continuing workflow with empty Federal Register records.",
      original_error: response
    }
  }
];
